// Function to extract car marque from club title
function extractMarque(title) {
    // Common car manufacturers/marques to look for in club names
    const marques = [
        "AC",
        "AJS",
        "Alfa Romeo",
        "Allard",
        "Alpine",
        "Alvis",
        "Ariel",
        "Armstrong Siddeley",
        "Arrol-Johnston",
        "Aston Martin",
        "Audi",
        "Austin",
        "Austin-Healey",
        "Bean",
        "Bentley",
        "Berkeley",
        "BMW",
        "Bond",
        "Bricklin",
        "Bristol",
        "BSA",
        "Buell",
        "Bugatti",
        "Buick",
        "Cadillac",
        "Capri",
        "Caterham",
        "Chevrolet",
        "Chrysler",
        "Citroën",
        "Cortina",
        "CX500",
        "DAF",
        "Daimler",
        "Datsun",
        "De Tomaso",
        "DeLorean",
        "DKW",
        "Dodge",
        "Ducati",
        "E30",
        "Escort",
        "Ferrari",
        "Fiat",
        "Ford",
        "Gilbern",
        "Gilera",
        "Gordon-Keeble",
        "GT6",
        "Healey",
        "Heinkel",
        "Hillman",
        "Honda",
        "Humber",
        "Imp",
        "ISO",
        "Jaguar",
        "Jawa",
        "Jensen",
        "Jowett",
        "Kawasaki",
        "Lambretta",
        "Lancia",
        "Lanchester",
        "Land Rover",
        "Lea-Francis",
        "Lincoln",
        "Lotus",
        "Marcos",
        "Maserati",
        "Matchless",
        "Mazda",
        "McLaren",
        "Mercedes-Benz",
        "Messerschmitt",
        "MG",
        "Mini",
        "Mitsubishi",
        "Montesa",
        "Morgan",
        "Morris",
        "Nissan",
        "Norton",
        "NSU",
        "Oldsmobile",
        "Panhard",
        "Panther",
        "Peerless",
        "Penton",
        "Peugeot",
        "Plymouth",
        "Pontiac",
        "Porsche",
        "Reliant",
        "Renault",
        "Riley",
        "Rolls-Royce",
        "Rover",
        "Royal Enfield",
        "Saab",
        "Scimitar",
        "Singer",
        "Sprite",
        "Standard",
        "Stutz",
        "Subaru",
        "Sunbeam",
        "Suzuki",
        "Talbot",
        "Tatra",
        "Toyota",
        "Triumph",
        "Tucker",
        "TVR",
        "Vauxhall",
        "Velocette",
        "Vespa",
        "Vincent",
        "Volkswagen",
        "Volvo",
        "Wartburg",
        "Willys",
        "Wolseley",
        "Yamaha",
        "Zündapp"
];

    // First check for exact matches of marques in the title
    for (const marque of marques) {
        if (title.includes(marque)) {
            // Special case for model-specific clubs where the model is mentioned but belongs to a parent marque
            if (title.includes("Cortina") || title.includes("Capri") || title.includes("Escort")) {
                return "Ford";
            }
            if (title.includes("Dub") || title.includes("VW")) {
                return "Volkswagen";
            }
            if (title.includes("E30")) {
                return "BMW";
            }
            if (title.includes("Sprite")) {
                return "Austin-Healey";
            }
            if (title.includes("GT6")) {
                return "Triumph";
            }
            
            if (title.includes("CX500")) {
                return "Honda";
            }
            return marque;
        }
    }

    // Check for patterns like "XYZ Car Club" or "ABC Owners Club" where XYZ/ABC might be the marque
    const patterns = [
        /^(\w+)\s+Car\s+Club/i,
        /^(\w+)\s+(Owners|Owner's)\s+Club/i,
        /^(\w+)\s+Drivers\s+Club/i,
        /^(\w+)\s+Enthusiasts\s+Club/i,
        /^(\w+)\s+Register/i,
        /^The\s+(\w+)\s+Club/i,
        /^(\w+)\s+Classic\s+(Car|Motorcycle)\s+Club/i,
        /^(\w+)\s+Club\s+of/i,
        /^(\w+)\s+Mk\d+\s+Club/i,
        /^(\w+)\s+Motor\s+Club/i,
        /^(\w+)\s+Motorcycle\s+Club/i,
        /^Club\s+(\w+)/i,
    ];

    for (const pattern of patterns) {
        const match = title.match(pattern);
        if (match && match[1]) {
            const possibleMarque = match[1];
            
            // Exclude common words that aren't marques
            if (["The", "Classic", "Vintage", "Historic", "Motor", "Motorcycle"].includes(possibleMarque)) {
                continue;
            }
            
            // Handle special cases
            if (possibleMarque === "Cortina" || possibleMarque === "Capri" || possibleMarque === "Escort") {
                return "Ford";
            }

            
            return possibleMarque;
        }
    }

    // Handle specific pattern cases like "Mk1 Cortina Owners Club" or "E30 BMW Club"
    const modelPatterns = [
        /Mk\d+\s+(\w+)/i,
        /(\w+)\s+Mk\d+/i,
        /E\d+\s+(\w+)/i,
    ];

    for (const pattern of modelPatterns) {
        const match = title.match(pattern);
        if (match && match[1]) {
            const model = match[1];
            // Map known models to their manufacturers
            if (model === "Cortina" || model === "Capri" || model === "Escort") {
                return "Ford";
            }
            if (model === "BMW") {
                return "BMW";
            }
            return model;
        }
    }

    // Check for "model type" patterns like "Austin A40"
    const marqueModelPatterns = [];
    for (const marque of marques) {
        marqueModelPatterns.push(new RegExp(`${marque}\\s+[A-Z0-9-]+`, 'i'));
    }

    for (const pattern of marqueModelPatterns) {
        if (pattern.test(title)) {
            // Extract the marque from the matched text
            for (const marque of marques) {
                if (new RegExp(`^${marque}\\s+`, 'i').test(title)) {
                    return marque;
                }
            }
        }
    }

    // Handle types of clubs that are clearly not marque-specific
    if (/Classic\s+(Car|Motorcycle|Motor)/i.test(title) || 
        /Vintage\s+(Car|Motorcycle|Motor)/i.test(title) ||
        /Historic\s+(Car|Motorcycle|Motor)/i.test(title)) {
        return "Classic";
    }

    // Determine the marque based on club category if available
    if (title.toLowerCase().includes("motorcycle")) {
        return "Motorcycle";
    }
    
    if (title.toLowerCase().includes("scooter")) {
        return "Scooter";
    }

    // Default if no marque found
    return "Classic";
}

